#!/usr/bin/env bash
# Quick gate, full gate and CI for a repository with more than one stack.
# Generated by /izi:kickoff; it's the project's script, edit it freely.
#   scripts/izi-check.sh           quick gate (IZI_CHECK): only the stacks with a file in $IZI_CHANGED
#   scripts/izi-check.sh --all     full gate: every stack
#   scripts/izi-check.sh <stack>   one stack, e.g. a CI job
# Each check runs inside its stack's directory, with IZI_CHANGED rewritten
# to that stack's files, relative to that directory.

set -euo pipefail
cd "$(dirname "$0")/.."

# One line per stack: name|directory|check command
stacks=(
  "<name>|<directory>|<check command>"
)

target="${1:-}"
ran=0
failed=0
for line in "${stacks[@]}"; do
  IFS='|' read -r name dir cmd <<<"$line"
  files=""
  for f in ${IZI_CHANGED:-}; do
    [[ "$f" == "$dir"/* ]] && files="$files ${f#"$dir"/}"
  done
  if [[ -z "$target" ]]; then
    [[ -n "$files" ]] || continue
  elif [[ "$target" != "--all" && "$target" != "$name" ]]; then
    continue
  fi
  ran=1
  echo "== $name ($dir)"
  # Explicit check: bash 3.2 (macOS) ignores set -e for a failing subshell here.
  if ! (cd "$dir" && IZI_CHANGED="${files# }" bash -c "$cmd"); then
    failed=1
  fi
done

if [[ -n "$target" && "$target" != "--all" && $ran == 0 ]]; then
  echo "Unknown stack: $target" >&2
  exit 2
fi
exit "$failed"
